def backfill_existing_payments(apps, schema_editor):
    """
    Antes de esta Fase, todo Payment existente correspondía a una orden PAID
    (el pago se creaba y la orden pasaba a PAID de inmediato). Se backfillea:
      - status='approved' (transacciones ya asimiladas)
      - approved_at=payment_date (snapshot razonable)
      - fee_rate=3.50 para CARD, 0 para el resto (regla hardcodeada previa)
    """
