    for payment in Payment.objects.all():
        payment.status = 'approved'
        payment.approved_at = payment.payment_date
        payment.fee_rate = 3.50 if payment.method == 'CARD' else 0
        payment.save(update_fields=['status', 'approved_at', 'fee_rate'])


